import bpy

CONCAVE = '-col'
CONVEX = '-convcol'

concave_prefixes = ('base', 'road_', 'building_')
convex_prefixes = ('bench', 'box_', 'dumpster', 'firehydrant', 'streetlight',
                   'trafficlight_', 'trash_', 'watertower')
car_bodies = ('car_hatchback', 'car_police', 'car_stationwagon', 'car_taxi')
skip_substrings = ('_wheel_',)
skip_prefixes = ('bush',)

def strip_suffix(n):
    for s in ('-convcolonly', '-convcol', '-colonly', '-col'):
        if n.endswith(s):
            return n[:-len(s)]
    return n

count = {'col': 0, 'convcol': 0, 'skipped': 0}
for o in bpy.data.objects:
    n = strip_suffix(o.name)
    if any(s in n for s in skip_substrings) or n.startswith(skip_prefixes):
        o.name = n
        count['skipped'] += 1
    elif n.startswith(concave_prefixes):
        o.name = n + CONCAVE
        count['col'] += 1
    elif n.startswith(car_bodies) or n.startswith(convex_prefixes):
        o.name = n + CONVEX
        count['convcol'] += 1
    else:
        o.name = n
        count['skipped'] += 1

print('RESULT:', count)
for o in bpy.data.objects[:8]:
    print(' ', o.name)

